theme.root_css:
:root {
  /* Colores Corporativos Clonados */
  --primary: #d03782;
  --secondary: #dddddd;
  --accent: #999999;

  /* Entorno Dark Mode Técnico */
  --bg-dark: #0b1329;
  --bg-card: #16203a;
  --text-main: #f8fafc;

  /* Geometría y Tipografía */
  --border-radius: 4px;
  --font-family: 'Montserrat', "Helvetica Neue", Helvetica, sans-serif;
}
